// Transpiled to HLSL using Milkwave
#define tx sin(uTime)*0.5+1
// 0.5 <= tx <= 1.5
vec3 palette ( float t ) {
t*=0.5;
vec3 a = vec3(0.5, 0.5, 0.5);
vec3 b = vec3(0.5, 0.5, 0.5);
vec3 c = vec3(1.0, 1.1, 1.0);
vec3 d = vec3(0.263, 0.416, 0.557);
#ifdef bass_smooth
d -= (int)vis_version > 2 ? 1.0 * vis_intensity+vis_shift : (1.5*smoothstep( 0.0 , 2.0 ,(int)vis_version == 1 ? bass_smooth : audioLowSmooth))*vis_intensity+vis_shift;
#else
d -= 0.2*smoothstep( 0.0 , 2.0 ,audioLowSmooth);
#endif
return a - b*cos(5.28318*(c*t+d) );
}
fragColor = vec4(finalColor, 1.0);
ret = fragColor;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec4 fragColor = 0;
// CONV: Center on screen, then try some uAspect correction
uv = (uv * 2.0) - 1.0;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
uv *= 0.5+(sin(uTime*0.2)*0.2);
vec2 fragCoord  = uv;
// vec2 uv = (fragCoord * 2.0 - uv.xy) / uv.y;
vec2 uv0 = uv;
vec3 finalColor = vec3(0.0, 0.0, 0.0);
for (float i = 0.0; i < 5.0; i++) {
uv = fract(uv * 1.6) - 0.5;
float d = length(uv);
vec3 col = palette(length(uv0) + uTime);
d = sin(d*8. +uTime)/8.;
d = abs(d);
d = pow(0.01 / d, 1.8);
finalColor += col * d;
  fragColor = vec4(ret, 1.0);
}

